// Turns the approved opening-round fan lines (PIC/team/openers/openers.json, Itzik's Word of 15.10) into src/data/openersText.ts.
//   node scripts/gen-openers.cjs
const fs = require('fs');
const rows = JSON.parse(fs.readFileSync('PIC/team/openers/openers.json', 'utf8'));
const out = `/**
 * The fan lines of the opening rounds (Itzik, 15.10, approved in the Word of the same day): on the eve of a season's first
 * rounds a fan talks about the season ahead and never about a table, a score or a result. Generated by scripts/gen-openers.cjs
 * from PIC/team/openers/openers.json. {rival}, {city} and {club} are slots.
 * when: home or away night, or either. season: any start, the start after a promotion, or a new season not after a promotion.
 * top: fit for the professional top flight.
 */
export interface OpenerLine {
  id: string; voice: string; when: 'home' | 'away' | 'any'; season: 'any' | 'promoted' | 'newSeason'; top: boolean; text: string;
}
export const OPENERS: OpenerLine[] = ${JSON.stringify(rows.map(r => ({ id: r.id, voice: r.voice, when: r.when, season: r.season, top: !!r.top, text: r.text })), null, 1)};
`;
fs.writeFileSync('src/data/openersText.ts', out);
console.log(rows.length, 'lines');
